    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif expr[i] in '+-*/()':
            tokens.append((expr[i], expr[i]))
            i += 1
        else:
            i += 1

    pos = 0

    def parse_expr():
        nonlocal pos
        left = parse_term()
        while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
            op = tokens[pos][0]
            pos += 1
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

