            op = tokens[pos][0]
            pos += 1
            right = parse_unary()
            if op == '*':
                left = left * right
            else:
                # Integer division truncating toward zero
                if (left < 0) != (right < 0) and left % right != 0:
                    left = left // right + 1
                else:
                    left = left // right
        return left

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos][0] == '-':
            pos += 1
            return -parse_unary()
        elif pos < len(tokens) and tokens[pos][0] == '+':
            pos += 1
            return parse_unary()
        else:
            return parse_primary()

