        nonlocal pos
        if pos < len(tokens) and tokens[pos][0] == 'NUM':
            val = tokens[pos][1]
            pos += 1
            return val
        elif pos < len(tokens) and tokens[pos][0] == '(':
            pos += 1
            result = parse_expr()
            pos += 1  # skip ')'
            return result
        return 0

    return parse_expr()

